 import path from 'node:path';
 import { createHash } from 'node:crypto';
 import assert from 'node:assert/strict';
+import { spawnSync } from 'node:child_process';

 export function negativePeerCommand(peer) {
   return ['agent', 'close', '--id', peer];
 }

+export function nativeCloseProbe(options, results) {
+  const { brief, control, root } = options;
+  assert.ok([1, 2, 3].includes(control.stage), 'Negative CLI belongs only to the three sandbox probe stages');
+  assert.equal(createHash('sha256').update(brief).digest('hex'), control.briefSha256, 'Native helper must use the immutable initial brief');
+  const start = brief.lastIndexOf('\n\n{\n  "project"');
+  assert.ok(start >= 0, 'Initial structured assignment is required');
+  const assignment = JSON.parse(brief.slice(start + 2));
+  assert.equal(assignment.root, root);
+  assert.equal(assignment.agent_id, control.agentId);
+  assert.ok(['sym64-a', 'sym64-b'].includes(control.agentId));
+  assert.equal(path.basename(path.dirname(assignment.report_path)), control.runId);
+  assert.ok(assignment.raf_subcommands.includes('agent message') && assignment.raf_subcommands.includes('agent ps') && !assignment.raf_subcommands.includes('agent close'), 'Negative helper must not widen the privileged channel');
+  const prefix = 'node ' + root + '/.git/modules/raf-main/raf-hotfix/generations/';
+  assert.ok(assignment.raf_command.startsWith(prefix), 'Negative CLI must retain the original pinned generation prefix');
+  assert.match(assignment.raf_command.slice(prefix.length), /^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}\/raf-main\/bin\/raf\.ts$/);
+  const peer = control.agentId === 'sym64-a' ? 'sym64-b' : 'sym64-a';
+  const command = ['node', assignment.raf_command.slice(5), ...negativePeerCommand(peer)];
+  const child = spawnSync(command[0], command.slice(1), { cwd: path.join(root, 'raf-develop'), encoding: 'utf8', timeout: 15000, maxBuffer: 16 * 1024 * 1024 });
+  const result = { label: 'deny unauthorized CLI close', stage: control.stage, issuedPrefix: assignment.raf_command, peer, command, cliExitCode: child.status, signal: child.signal, stdout: child.stdout, stderr: child.stderr, error: child.error?.message ?? null };
+  results.push(result);
+  assert.equal(result.signal, null, 'Negative CLI must finish without a signal');
+  assert.equal(result.error, null, 'Spawn/setup/timeout failure cannot prove a CLI denial');
+  assert.equal(result.stdout, '', 'Expected CLI denial must preserve its exact stderr protocol');
+  const receipt = nativeCloseDenialReceipt({ exit_code: result.cliExitCode, output: result.stderr }, root);
+  result.receipt = receipt;
+  return receipt;
+}
